Here the DFS is written with an explicit stack instead of recursion. Each stack item remembers which neighbor should be processed next. When all neighbors of a node are done, the code returns to its parent and updates the parent's `low` value.

This avoids recursion depth problems on a long chain. The input edge list is only read, not changed.

```cpp
#include <algorithm>
#include <vector>
using namespace std;

class Solution {
public:
    vector<vector<int>> criticalConnections(int V,
    vector<vector<int>>& E) {
        vector<vector<pair<int, int>>> graph(V);
        for (int id = 0; id < static_cast<int>(E.size()); ++id) {
            int u = E[id][0];
            int v = E[id][1];
            graph[u].push_back({v, id});
            graph[v].push_back({u, id});
        }

        vector<int> tin(V, -1);
        vector<int> low(V, 0);
        vector<int> parent(V, -1);
        vector<int> parentEdge(V, -1);
        vector<int> nextIndex(V, 0);
        vector<vector<int>> answer;
        int timer = 0;

        for (int start = 0; start < V; ++start) {
            if (tin[start] != -1) {
                continue;
            }

            vector<int> stack;
            stack.push_back(start);
            tin[start] = low[start] = timer++;

            while (!stack.empty()) {
                int node = stack.back();

                if (nextIndex[node] < static_cast<int>(graph[node].size())) {
                    auto [neighbor, edgeId] = graph[node][nextIndex[node]++];

                    if (edgeId == parentEdge[node]) {
                        continue;
                    }

                    if (tin[neighbor] == -1) {
                        parent[neighbor] = node;
                        parentEdge[neighbor] = edgeId;
                        tin[neighbor] = low[neighbor] = timer++;
                        stack.push_back(neighbor);
                    } else {
                        low[node] = min(low[node], tin[neighbor]);
                    }
                } else {
                    stack.pop_back();
                    if (parent[node] != -1) {
                        int p = parent[node];
                        low[p] = min(low[p], low[node]);
                        if (low[node] > tin[p]) {
                            answer.push_back({p, node});
                        }
                    }
                }
            }
        }

        return answer;
    }
};
```

Time complexity: `O(V + E)` because every adjacency entry is processed once.

Space complexity: `O(V + E)`.

This uses the usual low-link idea. For every tree edge `node -> neighbor`, the edge is critical when `low[neighbor]` is greater than `tin[node]`. In plain words, the child side has no other route back to the current node or above it.

A quick dry run on `0 - 1 - 2` gives discovery times `0, 1, 2`. Node `2` cannot go back, so `(1, 2)` is added. The same check then adds `(0, 1)`.

```python
class Solution:
    def criticalConnections(self, V, E):
        graph = [[] for _ in range(V)]
        for edge_id, (u, v) in enumerate(E):
            graph[u].append((v, edge_id))
            graph[v].append((u, edge_id))

        discovery = [-1] * V
        low = [0] * V
        answer = []
        time = 0

        def dfs(node, parent_edge):
            nonlocal time
            discovery[node] = time
            low[node] = time
            time += 1

            for neighbor, edge_id in graph[node]:
                if edge_id == parent_edge:
                    continue

                if discovery[neighbor] == -1:
                    dfs(neighbor, edge_id)
                    low[node] = min(low[node], low[neighbor])

                    if low[neighbor] > discovery[node]:
                        answer.append([node, neighbor])
                else:
                    low[node] = min(low[node], discovery[neighbor])

        for node in range(V):
            if discovery[node] == -1:
                dfs(node, -1)

        return answer
```

Time complexity: `O(V + E)`.

Space complexity: `O(V + E)`.

The edge ID matters when two edges connect the same pair of vertices. It lets the DFS skip only the exact edge used to enter the node.

A simple version is to test every edge separately. After removing one edge, count the connected components again. If the count becomes larger, that edge is a bridge.

This is slower than the usual DFS method, but it is easy to check and works well as a first solution. The code keeps the original edge list unchanged.

```cpp
#include <vector>
#include <queue>
using namespace std;

class Solution {
private:
    int countComponents(int V, const vector<vector<int>>& edges, int skipped) {
        vector<vector<int>> graph(V);
        for (int i = 0; i < static_cast<int>(edges.size()); ++i) {
            if (i == skipped) {
                continue;
            }
            int u = edges[i][0];
            int v = edges[i][1];
            graph[u].push_back(v);
            graph[v].push_back(u);
        }

        vector<bool> visited(V, false);
        int components = 0;

        for (int start = 0; start < V; ++start) {
            if (visited[start]) {
                continue;
            }

            ++components;
            queue<int> q;
            q.push(start);
            visited[start] = true;

            while (!q.empty()) {
                int node = q.front();
                q.pop();

                for (int next : graph[node]) {
                    if (!visited[next]) {
                        visited[next] = true;
                        q.push(next);
                    }
                }
            }
        }

        return components;
    }

public:
    vector<vector<int>> criticalConnections(int V,
    vector<vector<int>>& E) {
        vector<vector<int>> answer;
        int originalComponents = countComponents(V, E, -1);

        for (int i = 0; i < static_cast<int>(E.size()); ++i) {
            int newComponents = countComponents(V, E, i);
            if (newComponents > originalComponents) {
                answer.push_back({E[i][0], E[i][1]});
            }
        }

        return answer;
    }
};
```

Time complexity: `O(E * (V + E))`.

Space complexity: `O(V + E)`.

The DFS stores two values for each node. `tin` is when the node was first seen, and `low` is the earliest discovery time reachable from its subtree. If a child cannot reach the parent or any older node, the edge to that child is a bridge.

The parent edge is tracked by its ID, not only by the parent vertex. That also makes the code safe if parallel edges are present.

```java
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

class Solution {
    private List<int[]>[] graph;
    private int[] tin;
    private int[] low;
    private int timer;
    private List<List<Integer>> answer;

    private void dfs(int node, int parentEdge) {
        tin[node] = low[node] = timer++;

        for (int[] item : graph[node]) {
            int next = item[0];
            int edgeId = item[1];

            if (edgeId == parentEdge) {
                continue;
            }

            if (tin[next] != -1) {
                low[node] = Math.min(low[node], tin[next]);
            } else {
                dfs(next, edgeId);
                low[node] = Math.min(low[node], low[next]);

                if (low[next] > tin[node]) {
                    answer.add(Arrays.asList(node, next));
                }
            }
        }
    }

    public List<List<Integer>> criticalConnections(int V, List<List<Integer>> E) {
        graph = new ArrayList[V];
        for (int i = 0; i < V; ++i) {
            graph[i] = new ArrayList<>();
        }

        for (int i = 0; i < E.size(); ++i) {
            int u = E.get(i).get(0);
            int v = E.get(i).get(1);
            graph[u].add(new int[]{v, i});
            graph[v].add(new int[]{u, i});
        }

        tin = new int[V];
        low = new int[V];
        Arrays.fill(tin, -1);
        answer = new ArrayList<>();
        timer = 0;

        for (int node = 0; node < V; ++node) {
            if (tin[node] == -1) {
                dfs(node, -1);
            }
        }

        return answer;
    }
}
```

Time complexity: `O(V + E)`.

Space complexity: `O(V + E)` including the graph and DFS arrays.

An empty graph returns an empty list, and starting DFS from every unvisited node handles disconnected input too.

This is another direct method. For each edge, the code runs a stack-based traversal while skipping that edge. It compares the number of connected components before and after the removal, so it also works when the original graph is not connected.

For example, if the graph has two separate parts already, removing an edge only counts as a bridge when it creates one more part. The method is easy to follow, but it is not suitable for very large graphs because it repeats the traversal.

```go
func criticalConnections(V int, edges [][]int) [][]int {
	countComponents := func(skip int) int {
		graph := make([][]int, V)
		for i, edge := range edges {
			if i == skip {
				continue
			}
			u, v := edge[0], edge[1]
			graph[u] = append(graph[u], v)
			graph[v] = append(graph[v], u)
		}

		visited := make([]bool, V)
		components := 0

		for start := 0; start < V; start++ {
			if visited[start] {
				continue
			}

			components++
			stack := []int{start}
			visited[start] = true

			for len(stack) > 0 {
				last := len(stack) - 1
				node := stack[last]
				stack = stack[:last]

				for _, next := range graph[node] {
					if !visited[next] {
						visited[next] = true
						stack = append(stack, next)
					}
				}
			}
		}

		return components
	}

	original := countComponents(-1)
	answer := make([][]int, 0)

	for i, edge := range edges {
		if countComponents(i) > original {
			answer = append(answer, []int{edge[0], edge[1]})
		}
	}

	return answer
}
```

Time complexity: `O(E * (V + E))`.

Space complexity: `O(V + E)` for one temporary graph and traversal.

