class Solution {
    public List<List<Integer>> criticalConnections(int V, List<List<Integer>> E) {

        List<Integer>[] adj = new ArrayList[V];
        for(int i=0; i<V; i++) adj[i] = new ArrayList<>();
        for(List<Integer> edge : E){
            adj[edge.get(0)].add(edge.get(1));
            adj[edge.get(1)].add(edge.get(0));
        }
        int[] time = new int[V];
        int[] mini = new int[V];
        boolean[] visited = new boolean[V];
        ArrayList<List<Integer>> bridges = new ArrayList<>();
        dfs(0, -1, adj, time, mini, bridges, visited, 1);
        return bridges;
    }

    void dfs(int V, int parent, List<Integer>[] adj ,int[] time, int[] mini, ArrayList<List<Integer>> bridges, boolean[] visited, int timer){
        visited[V]=true;
        time[V]=mini[V]=timer;
        for(int ad : adj[V]){
            if(ad == parent) continue;
            if(!visited[ad]){
                dfs(ad, V, adj, time, mini, bridges, visited, ++timer);
                mini[V] = Math.min(mini[V], mini[ad]);
                if(time[V] < mini[ad]){
                    bridges.add(Arrays.asList(V, ad));
                }
            }else{
                mini[V] = Math.min(mini[V], mini[ad]);
            }
        }
    }

}


